class Solution {
    longestPalindrome(s) {
        const manacher = (s) => {
            const t = '#' + s.split('').join('#') + '#';
            const n = t.length;
            const p = new Array(n).fill(0);
            let l = 0, r = 0;
            for (let i = 0; i < n; i++) {
                p[i] = i < r ? Math.min(r - i, p[l + (r - i)]) : 0;
                while (i + p[i] + 1 < n && i - p[i] - 1 >= 0
                       && t[i + p[i] + 1] === t[i - p[i] - 1]) {
                    p[i]++;
                }
                if (i + p[i] > r) {
                    l = i - p[i];
                    r = i + p[i];
                }
            }
            return p;
        };

        const p = manacher(s);
        let resLen = 0, centerIdx = 0;
        for (let i = 0; i < p.length; i++) {
            if (p[i] > resLen) {
                resLen = p[i];
                centerIdx = i;
            }
        }
        const resIdx = Math.floor((centerIdx - resLen) / 2);
        return s.substring(resIdx, resIdx + resLen);
    }
}

