func longestPalindrome(s string) string {
    manacher := func(s string) []int {
        var sb strings.Builder
        sb.WriteString("#")
        for _, ch := range s {
            sb.WriteRune(ch)
            sb.WriteString("#")
        }
        t := sb.String()
        n := len(t)
        p := make([]int, n)
        l, r := 0, 0
        for i := 0; i < n; i++ {
            if i < r {
                p[i] = min(r-i, p[l+(r-i)])
            } else {
                p[i] = 0
            }
            for i+p[i]+1 < n && i-p[i]-1 >= 0 && t[i+p[i]+1] == t[i-p[i]-1] {
                p[i]++
            }
            if i+p[i] > r {
                l, r = i-p[i], i+p[i]
            }
        }
        return p
    }

    p := manacher(s)
    resLen, centerIdx := 0, 0
    for i, v := range p {
        if v > resLen {
            resLen = v
            centerIdx = i
        }
    }
    resIdx := (centerIdx - resLen) / 2
    return s[resIdx : resIdx+resLen]
}

